def getmodified(self, path):
    # type: (Text) -> Optional[datetime]
    """Get the modification time of a file.

    Uses the MDTM command if supported, otherwise falls back to
    parsing the modification time from the directory listing.

    Returns:
        `~datetime.datetime`: the modification time, or `None` if
        it cannot be determined.
    """
    _path = self.validatepath(path)

    # Try MDTM first if supported
    if "MDTM" in self.features:
        with ftp_errors(self, path=path):
            try:
                response = self.ftp.sendcmd(
                    str("MDTM ") + _encode(_path, self.ftp.encoding)
                )
                # MDTM response format: 213 YYYYMMDDHHMMSS
                # Example: 213 20210825140215
                text = _decode(response, self.ftp.encoding)
                # Extract the timestamp after the status code
                parts = text.split()
                if len(parts) >= 2:
                    time_str = parts[1]
                    if len(time_str) >= 14:
                        return self._parse_ftp_time(time_str)
            except error_perm:
                pass  # Fall through to directory listing

    # Fall back to getinfo
    info = self.getinfo(_path, ("details",))
    return info.modified if info else None

def getinfo(self, path, namespaces=None):
    # type: (Text, Optional[Container[Text]]) -> Info
    _path = self.validatepath(path)
    namespaces = namespaces or ()

    if _path == "/":
        return Info(
            {
                "basic": {"name": "", "is_dir": True},
                "details": {"type": int(ResourceType.directory)},
            }
        )

    # If only "modified" detail is requested, try MDTM first
    if "modified" in namespaces and not self.supports_mlst:
        modified = self.getmodified(_path)
        if modified is not None:
            details = {"modified": modified}
            if "basic" in namespaces:
                details["name"] = basename(_path)
            if "type" in namespaces:
                details["type"] = int(ResourceType.file)
            return Info(details)

    if self.supports_mlst:
        with self._lock:
            with ftp_errors(self, path=path):
                response = self.ftp.sendcmd(
                    str("MLST ") + _encode(_path, self.ftp.encoding)
                )
            lines = _decode(response, self.ftp.encoding).splitlines()[1:-1]
            for raw_info in self._parse_mlsx(lines):
                return Info(raw_info)

    with ftp_errors(self, path=path):
        dir_name, file_name = split(_path)
        directory = self._read_dir(dir_name)
        if file_name not in directory:
            raise errors.ResourceNotFound(path)
        info = directory[file_name]
        return info

